/* Conteúdo das normas (explicação simples + exemplos) — lote 1: Estrutura Conceitual, NBC TG 01 a 07, 09 e 10.
   Elaborado por Claude em 27/10/2026 a partir das normas do CFC/CPC (texto de apoio, não substitui a norma). Só use "ref" quando o item da norma original é seguro; senão "ver norma". */
window.NBC_CONTEUDO = window.NBC_CONTEUDO || {};
(function () {
  var AUTOR = 'Claude (estudo das normas do CFC/CPC)', DATA = '27/10/2026';
  function C(cod, rev, o) { window.NBC_CONTEUDO[cod] = Object.assign({ revisao_base: rev, gerado_em: DATA, autor: AUTOR, aviso: '' }, o); }

  C('NBC TG ESTRUTURA CONCEITUAL', '', {
    resumo: 'A Estrutura Conceitual é a “constituição” da contabilidade: ela não manda contabilizar nada em especial, mas explica para quem serve a informação contábil, que qualidades ela precisa ter e o que são ativo, passivo, receita e despesa. Quando uma norma específica não resolve um caso, é nela que o contador se apoia.',
    objetivo: 'Dar a base de ideias para escrever e interpretar todas as demais normas e para decidir casos que nenhuma norma cobre.',
    pontos: [
      { titulo: 'Para quem a contabilidade é feita', texto: 'O relatório contábil de propósito geral serve principalmente a investidores, credores e financiadores, atuais e futuros, que não podem pedir informação sob medida à empresa.', ref: 'Objetivo do relatório financeiro' },
      { titulo: 'Duas qualidades fundamentais', texto: 'A informação precisa ser relevante (faz diferença na decisão de quem usa) e representar fielmente o que aconteceu (completa, neutra e sem erros).', ref: 'Características qualitativas' },
      { titulo: 'Quatro qualidades que melhoram a informação', texto: 'Comparabilidade (dá para comparar com outras empresas e períodos), verificabilidade, tempestividade (chega a tempo) e compreensibilidade (clara para quem se esforça em entender).', ref: 'Características qualitativas' },
      { titulo: 'Essência acima da forma', texto: 'O que vale é a realidade econômica da operação, não só o nome que o contrato dá. Um “aluguel” que na prática é uma compra financiada deve ser tratado como compra.', ref: 'Representação fiel' },
      { titulo: 'O que é ativo', texto: 'Ativo é um recurso econômico controlado pela empresa como resultado de eventos passados. Recurso econômico é um direito com potencial de gerar benefícios econômicos.', ref: 'Elementos das demonstrações' },
      { titulo: 'O que é passivo', texto: 'Passivo é uma obrigação presente da empresa de transferir um recurso econômico, resultante de eventos passados.', ref: 'Elementos das demonstrações' },
      { titulo: 'Receita e despesa', texto: 'Receita é o aumento de ativos ou a diminuição de passivos que aumenta o patrimônio líquido (sem ser aporte dos sócios). Despesa é o contrário: reduz o patrimônio líquido (sem ser distribuição aos sócios).', ref: 'Elementos das demonstrações' },
      { titulo: 'Quando reconhecer e quando tirar do balanço', texto: 'Só entra nas demonstrações o item que atende à definição e cuja informação seja relevante e represente fielmente. Sai do balanço quando a empresa perde o controle do ativo ou a obrigação deixa de existir.', ref: 'Reconhecimento e desreconhecimento' },
      { titulo: 'Como medir', texto: 'Existem duas famílias: custo histórico (o que foi pago) e valores correntes (valor justo, valor em uso, custo corrente). A norma escolhe a base conforme a informação mais útil para cada item.', ref: 'Mensuração' },
    ],
    termos: [
      { termo: 'Relatório financeiro de propósito geral', significado: 'O conjunto de demonstrações (balanço, resultado etc.) feito para quem usa a informação sem poder exigi-la sob medida.' },
      { termo: 'Representação fiel', significado: 'Retratar o fato como ele é: completo, neutro (sem manipular) e livre de erro material.' },
      { termo: 'Materialidade', significado: 'Uma informação é material se omiti-la ou errá-la pode mudar a decisão de quem usa o relatório.' },
      { termo: 'Valor corrente', significado: 'Medida atualizada na data do balanço (valor justo, valor em uso, custo corrente), ao contrário do custo histórico.' },
      { termo: 'Continuidade', significado: 'Pressuposto de que a empresa seguirá operando no futuro previsível, salvo indicação em contrário.' },
    ],
    exemplos: [
      { titulo: 'Escolha de qual informação divulgar', situacao: 'Uma loja de R$ 2 milhões de faturamento tem um litígio trabalhista provável de R$ 300 mil. O gerente acha melhor “não assustar” o banco.', tratamento: 'A informação é relevante e a omissão tornaria o balanço enganoso. A neutralidade exige divulgar e registrar o risco conforme a norma específica (provisão).', lancamento: 'D - Despesa com provisão trabalhista 300.000,00 / C - Provisão para contingências 300.000,00', ref: 'Relevância e neutralidade' },
      { titulo: 'Essência sobre a forma', situacao: 'A empresa assina um “contrato de locação” de um caminhão por 60 meses; no fim, o caminhão fica dela por R$ 1,00 e as parcelas pagam todo o valor do veículo.', tratamento: 'Na essência é uma compra financiada: a empresa registra o caminhão no imobilizado e a dívida, não só a despesa mensal de aluguel.', lancamento: 'D - Imobilizado (caminhão) 400.000,00 / C - Financiamentos a pagar 400.000,00', ref: 'Representação fiel' },
      { titulo: 'Definição de ativo — o que não é', situacao: 'A fábrica gastou R$ 50 mil treinando a equipe, mas os funcionários podem pedir demissão a qualquer momento.', tratamento: 'A empresa não controla o benefício futuro dos funcionários; não atende à definição de ativo. O gasto vai para despesa.', lancamento: 'D - Despesa com treinamento 50.000,00 / C - Caixa 50.000,00', ref: 'Definição de ativo' },
      { titulo: 'Definição de passivo', situacao: 'A empresa recebe R$ 20 mil adiantados de um cliente por uma mercadoria que será entregue no mês seguinte.', tratamento: 'Existe obrigação presente de entregar a mercadoria: é passivo (adiantamento de cliente), não receita.', lancamento: 'D - Caixa 20.000,00 / C - Adiantamento de clientes 20.000,00', ref: 'Definição de passivo' },
      { titulo: 'Receita de verdade', situacao: 'O dono coloca R$ 100 mil de dinheiro próprio na empresa para aumentar o capital.', tratamento: 'Aporte dos sócios aumenta o patrimônio líquido mas NÃO é receita.', lancamento: 'D - Caixa 100.000,00 / C - Capital social 100.000,00', ref: 'Definição de receita' },
      { titulo: 'Despesa x distribuição', situacao: 'A empresa paga R$ 30 mil de lucros aos sócios.', tratamento: 'Distribuição de lucros reduz o patrimônio líquido, mas não é despesa do período.', lancamento: 'D - Lucros a distribuir (PL) 30.000,00 / C - Caixa 30.000,00', ref: 'Definição de despesa' },
      { titulo: 'Comparabilidade', situacao: 'Uma empresa muda de método de custeio de estoque sem avisar e os dados de um ano ficam incomparáveis com o seguinte.', tratamento: 'Para a informação ser comparável, a mudança deve ser divulgada e os períodos ajustados, conforme a norma de políticas contábeis.', lancamento: '—', ref: 'Comparabilidade' },
      { titulo: 'Materialidade', situacao: 'Um erro de R$ 80 numa conta de R$ 12 milhões de ativos.', tratamento: 'É improvável que mude a decisão de alguém: é imaterial e não precisa ser corrigido nem divulgado separadamente.', lancamento: '—', ref: 'Materialidade' },
      { titulo: 'Custo histórico x valor corrente', situacao: 'Um terreno foi comprado por R$ 500 mil e hoje vale R$ 900 mil no mercado.', tratamento: 'Em geral, o terreno permanece pelo custo histórico no balanço (se o imobilizado usar o modelo do custo); o valor de mercado pode ser divulgado em nota.', lancamento: '—', ref: 'Mensuração' },
      { titulo: 'Desreconhecimento de um ativo', situacao: 'A empresa vende por R$ 70 mil um equipamento que custou R$ 120 mil e estava depreciado em R$ 60 mil.', tratamento: 'Perdeu o controle do ativo: retira o equipamento e a depreciação do balanço e reconhece o ganho de R$ 10 mil.', lancamento: 'D - Caixa 70.000,00 / D - Depreciação acumulada 60.000,00 / C - Imobilizado 120.000,00 / C - Ganho na venda de imobilizado 10.000,00', ref: 'Desreconhecimento' },
    ],
  });

  C('NBC TG 01', 'R4', {
    resumo: 'Os ativos não podem ficar no balanço por mais do que conseguem render. Se um ativo vale menos do que está registrado, a empresa precisa reduzir o valor contábil e reconhecer a perda. Esta norma ensina como descobrir se há perda e como calculá-la.',
    objetivo: 'Garantir que nenhum ativo esteja registrado por valor maior do que a empresa consegue recuperar com o uso ou a venda dele.',
    pontos: [
      { titulo: 'Valor contábil não pode superar o valor recuperável', texto: 'Se o valor contábil do ativo é maior que o que se espera recuperar dele, a diferença é uma perda por redução ao valor recuperável (impairment) e vai para o resultado.', ref: 'itens 1 a 5' },
      { titulo: 'Olhar para sinais a cada fechamento', texto: 'Em cada data de balanço a empresa deve perguntar se há indício de perda: queda de mercado, obsolescência, dano físico, desempenho pior que o previsto, juros mais altos.', ref: 'item 9' },
      { titulo: 'Teste obrigatório todo ano para alguns ativos', texto: 'Ágio por expectativa de rentabilidade futura (goodwill), intangíveis de vida útil indefinida e intangíveis ainda em desenvolvimento precisam do teste todo ano, mesmo sem indício.', ref: 'item 10' },
      { titulo: 'Valor recuperável = o maior de dois', texto: 'É o maior entre o valor justo líquido das despesas de venda e o valor em uso (fluxos de caixa futuros descontados). Basta um dos dois ser maior que o valor contábil para não haver perda.', ref: 'item 18' },
      { titulo: 'Ativos que geram caixa juntos', texto: 'Quando o ativo sozinho não gera entradas de caixa independentes, o teste é feito para a menor unidade geradora de caixa (UGC) a que ele pertence, como uma loja ou uma linha de produção.', ref: 'itens 65 a 108' },
      { titulo: 'A perda vai para o resultado', texto: 'A perda é reconhecida de imediato na despesa (ou na reserva de reavaliação se houver). Em UGC, ela reduz primeiro o ágio e depois os demais ativos proporcionalmente.', ref: 'itens 59 e 104' },
      { titulo: 'Reversão da perda', texto: 'Se as condições melhoram, a perda de ativos (exceto ágio) pode ser revertida até o limite do valor que teria sem a perda.', ref: 'itens 109 a 125' },
      { titulo: 'Ágio nunca reverte', texto: 'A perda reconhecida sobre o ágio por expectativa de rentabilidade futura não pode ser revertida depois.', ref: 'item 124' },
    ],
    termos: [
      { termo: 'Impairment', significado: 'Perda por redução ao valor recuperável: o ativo vale menos do que está no balanço.' },
      { termo: 'Valor em uso', significado: 'Valor presente dos fluxos de caixa que o ativo deve gerar enquanto for usado pela empresa.' },
      { termo: 'Valor justo líquido de despesas de venda', significado: 'O que se obteria vendendo o ativo no mercado, menos as despesas para vender.' },
      { termo: 'UGC (unidade geradora de caixa)', significado: 'O menor grupo de ativos que gera entradas de caixa em grande parte independentes de outros grupos.' },
      { termo: 'Ágio (goodwill)', significado: 'O que se pagou a mais ao comprar uma empresa, acima do valor justo dos ativos e passivos identificáveis.' },
    ],
    exemplos: [
      { titulo: 'Máquina com demanda em queda', situacao: 'Uma máquina está no balanço por R$ 500.000, mas o produto que ela fabrica perdeu mercado e a empresa só espera recuperar R$ 380.000 usando ou vendendo-a.', tratamento: 'Há perda de R$ 120.000, reconhecida no resultado.', lancamento: 'D - Perda por redução ao valor recuperável (resultado) 120.000,00 / C - (-) Perda por impairment – Imobilizado 120.000,00', ref: 'itens 59 e 60' },
      { titulo: 'Teste anual do ágio', situacao: 'Após comprar uma distribuidora, a empresa tem ágio de R$ 2.000.000. No teste anual, a unidade comprada vale R$ 1.700.000 a menos do que está registrado: R$ 300.000.', tratamento: 'Mesmo sem indício, o teste é anual. A perda reduz o ágio primeiro.', lancamento: 'D - Perda por impairment do ágio 300.000,00 / C - Ágio 300.000,00', ref: 'itens 10 e 104' },
      { titulo: 'Fábrica com incêndio', situacao: 'Um galpão contabilizado em R$ 1.200.000 foi parcialmente destruído por um incêndio e só vale R$ 700.000 no estado atual.', tratamento: 'Dano físico é indício claro. Reconhece-se a perda de R$ 500.000 (sem confundir com o seguro a receber, que é outro registro).', lancamento: 'D - Perda por redução ao valor recuperável 500.000,00 / C - Perda por impairment – Imobilizado 500.000,00', ref: 'item 12' },
      { titulo: 'UGC: loja deficitária', situacao: 'Uma loja (UGC) tem ativos contábeis de R$ 900.000 (R$ 600.000 de equipamentos e R$ 300.000 de benfeitorias). Pelos fluxos de caixa, só vale R$ 720.000.', tratamento: 'A perda de R$ 180.000 é rateada proporcionalmente entre os ativos da loja (sem levar nenhum abaixo do seu valor recuperável individual).', lancamento: 'D - Perda por impairment 180.000,00 / C - Perda por impairment – Equipamentos 120.000,00 / C - Perda por impairment – Benfeitorias 60.000,00', ref: 'itens 104 e 105' },
      { titulo: 'Intangível em desenvolvimento', situacao: 'Um software em desenvolvimento está em R$ 400.000, e a empresa ainda não pode usá-lo. Mesmo assim, a norma pede o teste anual.', tratamento: 'Faz-se o teste e, se o valor recuperável for R$ 350.000, registra-se a perda de R$ 50.000.', lancamento: 'D - Perda por impairment 50.000,00 / C - Perda por impairment – Intangível 50.000,00', ref: 'item 10' },
      { titulo: 'Sem perda: valor justo ajuda', situacao: 'Um terreno está contabilizado em R$ 800.000. O valor em uso é difícil de calcular, mas uma avaliação mostra valor justo líquido de despesas de venda de R$ 950.000.', tratamento: 'O valor recuperável é o maior dos dois (R$ 950.000): não há perda, e não precisa calcular o valor em uso.', lancamento: '—', ref: 'itens 18 a 20' },
      { titulo: 'Reversão de perda', situacao: 'Uma máquina teve perda de R$ 100.000 em 2024. Em 2026, o mercado se recuperou e o valor recuperável subiu.', tratamento: 'A perda é revertida, mas só até o valor que o ativo teria hoje (com depreciação normal) se a perda nunca existisse.', lancamento: 'D - (-) Perda por impairment – Imobilizado 90.000,00 / C - Reversão de perda por redução ao valor recuperável (resultado) 90.000,00', ref: 'itens 114 a 117' },
      { titulo: 'Ágio: sem reversão', situacao: 'A empresa teve perda de R$ 300.000 no ágio em 2026 e, em 2027, o negócio voltou a render muito bem.', tratamento: 'A perda do ágio NÃO pode ser revertida, mesmo com a recuperação.', lancamento: '—', ref: 'item 124' },
      { titulo: 'Indícios sem perda', situacao: 'A taxa de juros do mercado subiu, mas o valor em uso, recalculado, continua acima do valor contábil.', tratamento: 'Indício não obriga reconhecer perda; só obriga a testar. Aqui o teste não encontra perda.', lancamento: '—', ref: 'itens 9 a 12' },
      { titulo: 'Intangível de vida útil indefinida', situacao: 'Uma marca adquirida está no balanço por R$ 1.000.000, sem amortização. No teste anual, o valor recuperável é R$ 900.000.', tratamento: 'Perda de R$ 100.000 no resultado.', lancamento: 'D - Perda por impairment 100.000,00 / C - Marcas e patentes (redutora) 100.000,00', ref: 'item 10' },
    ],
  });

  C('NBC TG 02', 'R3', {
    resumo: 'Uma empresa pode vender em dólar, comprar em euro ou ter uma filial no exterior. Esta norma diz em que moeda cada operação deve ser registrada, a que taxa de câmbio converter e onde lançar os ganhos e perdas de câmbio.',
    objetivo: 'Padronizar como converter operações em moeda estrangeira e demonstrações de operações no exterior para a moeda em que a empresa apresenta suas contas.',
    pontos: [
      { titulo: 'Moeda funcional', texto: 'É a moeda do ambiente econômico principal em que a empresa opera (onde ela gera e gasta o caixa). Em geral, no Brasil, o real; mas uma exportadora de commodities pode ter outra.', ref: 'itens 8 e 9' },
      { titulo: 'Primeiro registro', texto: 'Toda operação em moeda estrangeira é convertida na moeda funcional pela taxa à vista da data da transação.', ref: 'item 21' },
      { titulo: 'No fechamento do balanço', texto: 'Itens monetários (caixa, contas a receber/pagar, empréstimos) são reconvertidos pela taxa de fechamento. Itens não monetários ao custo histórico (estoque, imobilizado) ficam pela taxa da data da transação.', ref: 'item 23' },
      { titulo: 'Variação cambial no resultado', texto: 'As diferenças de câmbio dos itens monetários vão para o resultado do período (ganho ou perda cambial).', ref: 'item 28' },
      { titulo: 'Operação no exterior', texto: 'Para consolidar uma controlada ou coligada no exterior: ativos e passivos pela taxa de fechamento; receitas e despesas pela taxa da data de cada transação (ou média, se for razoável).', ref: 'item 39' },
      { titulo: 'Ajuste acumulado de conversão', texto: 'As diferenças da conversão de operações no exterior não passam pelo resultado: ficam em outros resultados abrangentes (no patrimônio líquido) até a baixa do investimento.', ref: 'itens 39 e 48' },
      { titulo: 'Investimento líquido em operação no exterior', texto: 'Empréstimos de longo prazo à controlada no exterior sem previsão de pagamento podem ter a variação cambial lançada no patrimônio em vez do resultado nas demonstrações consolidadas.', ref: 'item 32' },
      { titulo: 'Moeda de apresentação', texto: 'A empresa pode apresentar demonstrações em outra moeda diferente da funcional; nesse caso aplica as regras de conversão do item 39.', ref: 'itens 38 a 43' },
    ],
    termos: [
      { termo: 'Moeda funcional', significado: 'A moeda do principal ambiente econômico em que a empresa opera.' },
      { termo: 'Item monetário', significado: 'Direito ou obrigação a receber/pagar um valor fixo ou determinável de dinheiro (caixa, clientes, fornecedores, empréstimos).' },
      { termo: 'Taxa de fechamento', significado: 'A taxa de câmbio à vista na data do balanço.' },
      { termo: 'Taxa à vista', significado: 'A taxa de câmbio para entrega imediata.' },
      { termo: 'Ajuste acumulado de conversão', significado: 'Conta no patrimônio que acumula as variações de câmbio da conversão de operações no exterior.' },
    ],
    exemplos: [
      { titulo: 'Compra de mercadoria importada', situacao: 'Em 10/03 a empresa compra US$ 10.000 em mercadorias a prazo. Dólar à vista: R$ 5,00.', tratamento: 'Registra o estoque e o fornecedor pela taxa da data da transação: R$ 50.000.', lancamento: 'D - Estoques 50.000,00 / C - Fornecedores estrangeiros 50.000,00', ref: 'item 21' },
      { titulo: 'Variação no fechamento (perda)', situacao: 'Em 31/03 o dólar sobe para R$ 5,30 e a dívida de US$ 10.000 ainda está aberta.', tratamento: 'O fornecedor é item monetário: reconverte a R$ 53.000. Perda cambial de R$ 3.000 no resultado. O estoque não muda.', lancamento: 'D - Variação cambial passiva (resultado) 3.000,00 / C - Fornecedores estrangeiros 3.000,00', ref: 'itens 23 e 28' },
      { titulo: 'Pagamento em outra taxa', situacao: 'Em 20/04 a empresa paga os US$ 10.000 com o dólar a R$ 5,20.', tratamento: 'O fornecedor estava em R$ 53.000; o pagamento custa R$ 52.000. A diferença de R$ 1.000 é ganho cambial do período.', lancamento: 'D - Fornecedores estrangeiros 53.000,00 / C - Caixa 52.000,00 / C - Variação cambial ativa 1.000,00', ref: 'item 28' },
      { titulo: 'Venda para o exterior a prazo', situacao: 'A empresa exporta por US$ 20.000 com o dólar a R$ 5,10 (R$ 102.000). No balanço o dólar está a R$ 4,90.', tratamento: 'O contas a receber é monetário: reconverte para R$ 98.000. Perda cambial de R$ 4.000.', lancamento: 'D - Variação cambial passiva 4.000,00 / C - Clientes no exterior 4.000,00', ref: 'itens 23 e 28' },
      { titulo: 'Estoque não é reconvertido', situacao: 'O estoque importado comprado a R$ 5,00 por dólar continua no balanço pelo valor de R$ 50.000, mesmo se o dólar subir.', tratamento: 'Item não monetário ao custo histórico mantém a taxa da data da transação.', lancamento: '—', ref: 'item 23' },
      { titulo: 'Empréstimo em moeda estrangeira', situacao: 'Empréstimo de US$ 100.000 tomado com o dólar a R$ 5,00. No fim do ano o dólar vai a R$ 5,40.', tratamento: 'A dívida passa a R$ 540.000; a diferença de R$ 40.000 é variação cambial passiva no resultado.', lancamento: 'D - Variação cambial passiva 40.000,00 / C - Empréstimos em moeda estrangeira 40.000,00', ref: 'itens 23 e 28' },
      { titulo: 'Controlada no exterior', situacao: 'Uma controlada na Argentina (moeda funcional diferente do real) tem patrimônio que, convertido, muda por causa do câmbio.', tratamento: 'Na consolidação, o ativo e o passivo são convertidos à taxa de fechamento; a diferença vai para “Ajuste acumulado de conversão” no patrimônio, não para o resultado.', lancamento: 'D - Investimentos em controlada 15.000,00 / C - Ajuste acumulado de conversão (outros resultados abrangentes) 15.000,00', ref: 'item 39' },
      { titulo: 'Receita da controlada no exterior', situacao: 'A controlada reconhece receitas ao longo do ano, com câmbio variando.', tratamento: 'Cada receita e despesa é convertida pela taxa da data da transação; na prática, é aceita uma taxa média do período se o câmbio não oscilar muito.', lancamento: '—', ref: 'item 39' },
      { titulo: 'Escolha da moeda funcional', situacao: 'Uma empresa brasileira exporta soja, tem preços e dívidas em dólar e o caixa dela gira em dólar.', tratamento: 'Pode concluir que a moeda funcional é o dólar, mesmo estando no Brasil, desde que isso reflita a realidade econômica.', lancamento: '—', ref: 'itens 9 e 10' },
      { titulo: 'Baixa do investimento no exterior', situacao: 'A empresa vende a controlada estrangeira; o ajuste acumulado de conversão no patrimônio era um ganho de R$ 80.000.', tratamento: 'Na venda, esse valor acumulado é reclassificado para o resultado do período.', lancamento: 'D - Ajuste acumulado de conversão 80.000,00 / C - Ganho na baixa de investimento (resultado) 80.000,00', ref: 'item 48' },
    ],
  });

  C('NBC TG 03', 'R3', {
    resumo: 'A Demonstração dos Fluxos de Caixa mostra, ao longo do período, de onde veio e para onde foi o dinheiro da empresa. Ela separa a movimentação em três grupos (operação, investimento e financiamento) e ajuda a responder: o lucro virou caixa?',
    objetivo: 'Dar a quem lê as contas a informação sobre as entradas e saídas de caixa do período, separadas por natureza.',
    pontos: [
      { titulo: 'Caixa e equivalentes de caixa', texto: 'Inclui o dinheiro em caixa e em bancos e aplicações de altíssima liquidez, com vencimento curto (em geral até 3 meses) e risco insignificante de variação de valor.', ref: 'itens 6 e 7' },
      { titulo: 'Três atividades', texto: 'Operacionais (o dia a dia: vendas, compras, salários, impostos), de investimento (compra e venda de imobilizado, investimentos) e de financiamento (empréstimos, capital, dividendos).', ref: 'item 10' },
      { titulo: 'Dois métodos para o fluxo operacional', texto: 'Direto (mostra recebimentos de clientes e pagamentos a fornecedores) ou indireto (parte do lucro e o ajusta pelos itens que não afetam o caixa). O CFC admite os dois; o direto é incentivado.', ref: 'itens 18 a 20' },
      { titulo: 'Juros e dividendos', texto: 'Juros e dividendos pagos ou recebidos têm tratamento definido: a empresa escolhe a classificação (operacional, investimento ou financiamento) e mantém o critério ao longo do tempo.', ref: 'itens 31 a 34' },
      { titulo: 'Transações que não usam caixa', texto: 'Compras financiadas diretamente pelo vendedor ou troca de dívida por ações não aparecem no fluxo, mas devem ser divulgadas em nota.', ref: 'item 43' },
      { titulo: 'Impostos sobre o lucro', texto: 'Em geral, os tributos sobre o lucro pagos entram como atividade operacional, salvo se puderem ser ligados a uma atividade de investimento ou financiamento específica.', ref: 'itens 35 a 36' },
      { titulo: 'Fluxos pelo valor líquido', texto: 'Algumas entradas e saídas podem ser mostradas líquidas, como recebimentos e pagamentos por conta de clientes quando o fluxo reflete a atividade do cliente, e não da empresa.', ref: 'itens 22 e 23' },
      { titulo: 'Conciliação com o balanço', texto: 'O total do fluxo do período deve fechar com a variação do caixa e equivalentes entre o início e o fim do ano, e a empresa deve reconciliar os valores com o balanço.', ref: 'item 45' },
    ],
    termos: [
      { termo: 'Equivalentes de caixa', significado: 'Aplicações de curtíssimo prazo, de alta liquidez, que viram dinheiro sem risco relevante de perda de valor.' },
      { termo: 'Atividades operacionais', significado: 'As atividades principais que geram receita da empresa e demais atividades que não são de investimento nem de financiamento.' },
      { termo: 'Atividades de investimento', significado: 'Aquisição e venda de ativos de longo prazo (imobilizado, intangível, participações societárias).' },
      { termo: 'Atividades de financiamento', significado: 'Atividades que mudam o tamanho e a composição do capital próprio e das dívidas da empresa.' },
      { termo: 'Método indireto', significado: 'Começa pelo lucro e o ajusta por depreciação, variações de contas a receber, estoques, fornecedores etc.' },
    ],
    exemplos: [
      { titulo: 'Recebimento de clientes (direto)', situacao: 'No mês a empresa recebe R$ 400.000 de clientes e paga R$ 250.000 a fornecedores e R$ 90.000 de salários.', tratamento: 'No método direto, os três valores aparecem nas atividades operacionais.', lancamento: '—', ref: 'itens 18 e 19' },
      { titulo: 'Método indireto — ajuste de depreciação', situacao: 'Lucro do ano R$ 200.000; depreciação R$ 60.000 (não saiu caixa); clientes aumentaram R$ 50.000; fornecedores aumentaram R$ 30.000.', tratamento: 'Caixa operacional = 200.000 + 60.000 − 50.000 + 30.000 = R$ 240.000.', lancamento: '—', ref: 'item 20' },
      { titulo: 'Compra de máquina', situacao: 'A empresa paga R$ 300.000 à vista por uma máquina.', tratamento: 'Saída de caixa de investimento (R$ 300.000).', lancamento: 'D - Imobilizado 300.000,00 / C - Caixa 300.000,00', ref: 'item 16' },
      { titulo: 'Venda de imobilizado', situacao: 'Vende um veículo antigo por R$ 40.000.', tratamento: 'Entrada de caixa de investimento (R$ 40.000); o ganho ou a perda aparece no resultado e é ajustado no método indireto.', lancamento: 'D - Caixa 40.000,00 / C - Imobilizado 40.000,00', ref: 'item 16' },
      { titulo: 'Empréstimo tomado', situacao: 'Recebe R$ 500.000 de um banco a pagar em 3 anos.', tratamento: 'Entrada de caixa de financiamento.', lancamento: 'D - Caixa 500.000,00 / C - Empréstimos 500.000,00', ref: 'item 17' },
      { titulo: 'Pagamento de dividendos', situacao: 'A empresa paga R$ 80.000 de dividendos aos sócios.', tratamento: 'Saída de caixa de financiamento (ou operacional, se a empresa adotar essa política e mantiver o critério).', lancamento: 'D - Dividendos a pagar 80.000,00 / C - Caixa 80.000,00', ref: 'itens 31 a 34' },
      { titulo: 'Aplicação como equivalente de caixa', situacao: 'Uma aplicação (CDB) de R$ 100.000 vence em 60 dias e pode ser resgatada sem risco relevante.', tratamento: 'Conta como equivalente de caixa; mover dinheiro do banco para esse CDB não é saída de caixa na demonstração.', lancamento: 'D - Equivalentes de caixa 100.000,00 / C - Bancos 100.000,00', ref: 'itens 6 e 7' },
      { titulo: 'Compra financiada pelo vendedor', situacao: 'Compra de equipamento de R$ 200.000 com financiamento direto do fornecedor, sem dinheiro entrar na empresa.', tratamento: 'Não é fluxo de caixa; deve ser divulgada em nota sobre transações sem caixa.', lancamento: 'D - Imobilizado 200.000,00 / C - Financiamentos 200.000,00', ref: 'item 43' },
      { titulo: 'Juros pagos', situacao: 'A empresa paga R$ 25.000 de juros sobre empréstimo.', tratamento: 'Classifica como operacional ou de financiamento, mantendo o mesmo critério todo ano, e divulga.', lancamento: 'D - Juros a pagar 25.000,00 / C - Caixa 25.000,00', ref: 'itens 31 e 33' },
      { titulo: 'Fechamento do fluxo', situacao: 'Caixa inicial R$ 120.000; operacional +240.000; investimento −260.000; financiamento +100.000.', tratamento: 'Variação do período +80.000, e o caixa final é R$ 200.000, que deve bater com o balanço.', lancamento: '—', ref: 'item 45' },
    ],
  });

  C('NBC TG 04', 'R4', {
    resumo: 'Intangível é um ativo que não tem corpo físico, como software, marcas, patentes e licenças. A norma explica quando um gasto com esse tipo de bem pode virar ativo (e quando precisa ser despesa), como amortizar e quando testar a perda de valor.',
    objetivo: 'Definir quando reconhecer um ativo intangível e como medi-lo e divulgá-lo.',
    pontos: [
      { titulo: 'O que é intangível', texto: 'Ativo não monetário, identificável e sem substância física. Para ser ativo a empresa precisa controlar o recurso e esperar benefícios econômicos futuros.', ref: 'itens 8 a 17' },
      { titulo: 'Pesquisa vai para despesa', texto: 'Gastos da fase de pesquisa (investigar, buscar conhecimento novo) são sempre despesa do período.', ref: 'itens 54 a 56' },
      { titulo: 'Desenvolvimento pode virar ativo', texto: 'Só se a empresa demonstrar: viabilidade técnica, intenção e capacidade de concluir e usar/vender, geração de benefícios, recursos para terminar e mensuração confiável dos gastos.', ref: 'item 57' },
      { titulo: 'O que NÃO pode ser ativado', texto: 'Marcas, títulos de publicações, listas de clientes e ágio gerados internamente não são reconhecidos como ativo.', ref: 'itens 48 e 63' },
      { titulo: 'Custo de aquisição', texto: 'Intangível comprado entra pelo preço de compra mais os gastos diretos para deixá-lo pronto para uso, descontados abatimentos.', ref: 'itens 24 a 33' },
      { titulo: 'Vida útil definida: amortiza', texto: 'Se a vida útil é definida, o bem é amortizado de forma sistemática pelo período em que traz benefícios. A vida útil e o método são revisados ao menos uma vez por ano.', ref: 'itens 88 a 106' },
      { titulo: 'Vida útil indefinida: não amortiza', texto: 'Não há limite previsível de benefícios, então não se amortiza, mas o ativo passa pelo teste anual de redução ao valor recuperável (NBC TG 01).', ref: 'itens 107 e 108' },
      { titulo: 'Baixa', texto: 'O ativo é baixado na venda ou quando não se esperam mais benefícios. O ganho ou a perda vai para o resultado.', ref: 'itens 112 a 117' },
    ],
    termos: [
      { termo: 'Amortização', significado: 'Distribuição do custo de um intangível ao longo da vida útil (equivale à depreciação do imobilizado).' },
      { termo: 'Vida útil', significado: 'Período em que se espera usar o ativo ou o número de unidades de produção esperadas.' },
      { termo: 'Identificável', significado: 'Pode ser separado da empresa (vendido, licenciado) ou decorre de direito contratual ou legal.' },
      { termo: 'Fase de pesquisa', significado: 'Etapa de investigação original com o objetivo de adquirir novo conhecimento.' },
      { termo: 'Fase de desenvolvimento', significado: 'Aplicação dos resultados da pesquisa em um plano ou projeto para produzir bem ou processo novo.' },
    ],
    exemplos: [
      { titulo: 'Compra de software pronto', situacao: 'A empresa compra uma licença de ERP por R$ 120.000, vida útil de 5 anos, com mais R$ 10.000 de implantação direta.', tratamento: 'Ativa R$ 130.000 e amortiza em 5 anos (R$ 26.000 por ano).', lancamento: 'D - Intangível – Software 130.000,00 / C - Caixa 130.000,00', ref: 'itens 24 e 27' },
      { titulo: 'Amortização mensal', situacao: 'Software de R$ 130.000 amortizado em 60 meses.', tratamento: 'Cada mês reconhece R$ 2.166,67 de amortização no resultado.', lancamento: 'D - Despesa de amortização 2.166,67 / C - Amortização acumulada – Software 2.166,67', ref: 'item 97' },
      { titulo: 'Pesquisa de nova fórmula', situacao: 'Um laboratório gasta R$ 300.000 pesquisando uma nova fórmula, sem saber ainda se funcionará.', tratamento: 'Fase de pesquisa: tudo despesa.', lancamento: 'D - Despesa de pesquisa 300.000,00 / C - Caixa 300.000,00', ref: 'itens 54 a 56' },
      { titulo: 'Desenvolvimento ativável', situacao: 'Depois de provar a viabilidade de um aplicativo, a empresa gasta R$ 200.000 desenvolvendo-o, com intenção e recursos para lançá-lo.', tratamento: 'Se todos os requisitos do item 57 estão atendidos, o gasto é ativado.', lancamento: 'D - Intangível em desenvolvimento 200.000,00 / C - Caixa 200.000,00', ref: 'item 57' },
      { titulo: 'Marca criada pela própria empresa', situacao: 'A empresa investe R$ 500.000 em publicidade para fortalecer a marca criada por ela.', tratamento: 'Marca gerada internamente não é ativo: o gasto é despesa.', lancamento: 'D - Despesa de publicidade 500.000,00 / C - Caixa 500.000,00', ref: 'item 63' },
      { titulo: 'Marca comprada', situacao: 'A empresa adquire a marca de terceiros por R$ 800.000.', tratamento: 'Aquisição separada é reconhecida como ativo. Se a vida útil for indefinida, não amortiza, mas passa por teste anual.', lancamento: 'D - Intangível – Marcas 800.000,00 / C - Caixa 800.000,00', ref: 'itens 25 e 107' },
      { titulo: 'Licença com prazo', situacao: 'A empresa compra uma licença de uso de 10 anos por R$ 100.000.', tratamento: 'Vida útil de 10 anos: amortiza R$ 10.000 por ano.', lancamento: 'D - Despesa de amortização 10.000,00 / C - Amortização acumulada 10.000,00', ref: 'item 97' },
      { titulo: 'Revisão de vida útil', situacao: 'Após 2 anos, a empresa percebe que o software ficará obsoleto em mais 2 anos, não em mais 3.', tratamento: 'Altera a estimativa de vida útil de forma prospectiva (do ano atual em diante), sem refazer o passado.', lancamento: '—', ref: 'item 104' },
      { titulo: 'Baixa de intangível', situacao: 'Uma patente com saldo de R$ 40.000 é abandonada, sem previsão de benefícios.', tratamento: 'Baixa o saldo para o resultado.', lancamento: 'D - Perda na baixa de intangível 40.000,00 / C - Intangível – Patentes 40.000,00', ref: 'item 112' },
      { titulo: 'Lista de clientes interna', situacao: 'A loja montou, com esforço próprio, um cadastro valioso de clientes.', tratamento: 'Listas de clientes geradas internamente não são reconhecidas.', lancamento: '—', ref: 'item 63' },
    ],
  });

  C('NBC TG 05', 'R3', {
    resumo: 'Quando a empresa negocia com quem tem ligação especial com ela (sócios, controladoras, diretores, familiares), os preços e condições podem não ser os de mercado. Esta norma obriga a divulgar essas transações e saldos, para que quem lê as contas saiba que elas existem.',
    objetivo: 'Garantir que as demonstrações divulguem o que a empresa tem, deve e negocia com suas partes relacionadas, e a remuneração dos administradores.',
    pontos: [
      { titulo: 'Quem é parte relacionada', texto: 'Controladora, controladas, coligadas, empreendimentos em conjunto, entidades sob controle comum, pessoal-chave da administração e seus familiares próximos, entre outros.', ref: 'item 9' },
      { titulo: 'Relações de controle sempre divulgadas', texto: 'A relação entre controladora e controladas deve ser divulgada mesmo que não tenha havido transações entre elas, indicando o nome da controladora direta e da controladora final.', ref: 'itens 13 a 16' },
      { titulo: 'Remuneração do pessoal-chave', texto: 'Divulgar o total pago a diretores e administradores, separado em benefícios de curto prazo, pós-emprego, outros de longo prazo, rescisão e pagamento em ações.', ref: 'item 17' },
      { titulo: 'Transações com partes relacionadas', texto: 'Divulgar natureza da relação, valor das transações, saldos a pagar/receber, prazos, garantias e provisões para créditos duvidosos ligados a elas.', ref: 'itens 18 a 24' },
      { titulo: 'Exemplos do que divulgar', texto: 'Compra ou venda de bens, serviços, aluguéis, empréstimos, garantias dadas, contratos de gerenciamento e compromissos futuros com partes relacionadas.', ref: 'item 21' },
      { titulo: 'Cuidado ao dizer “condições de mercado”', texto: 'A empresa só pode afirmar que a transação foi em condições equivalentes às de mercado se conseguir comprovar isso.', ref: 'item 23' },
      { titulo: 'Agrupamento permitido', texto: 'Itens de natureza semelhante podem ser divulgados de forma agregada, desde que a separação não seja necessária para entender o efeito.', ref: 'item 24' },
      { titulo: 'Isenções para o governo', texto: 'Entidades ligadas ao governo têm algumas dispensas de detalhar transações com outras entidades estatais, mas ainda precisam divulgar as relevantes.', ref: 'itens 25 a 27' },
    ],
    termos: [
      { termo: 'Parte relacionada', significado: 'Pessoa ou entidade ligada à empresa por controle, influência significativa, parentesco próximo ou posição de gestão-chave.' },
      { termo: 'Pessoal-chave da administração', significado: 'Quem tem autoridade para planejar, dirigir e controlar as atividades da empresa (diretores, conselheiros).' },
      { termo: 'Controle comum', significado: 'Duas empresas controladas pelo mesmo controlador.' },
      { termo: 'Familiares próximos', significado: 'Pessoas da família que podem influenciar ou ser influenciadas pela pessoa em suas relações com a empresa.' },
      { termo: 'Influência significativa', significado: 'Poder de participar das decisões financeiras e operacionais sem ter o controle.' },
    ],
    exemplos: [
      { titulo: 'Empréstimo do sócio à empresa', situacao: 'O sócio Pedro empresta R$ 150.000 à empresa a juros de 1% ao mês.', tratamento: 'É transação com parte relacionada: divulgar o valor, o prazo, os juros e o saldo no fim do ano.', lancamento: 'D - Caixa 150.000,00 / C - Empréstimos de sócios 150.000,00', ref: 'itens 18 e 21' },
      { titulo: 'Aluguel de imóvel do sócio', situacao: 'A empresa paga R$ 8.000/mês de aluguel de um imóvel de propriedade do sócio.', tratamento: 'Divulgar o contrato, o valor anual (R$ 96.000) e eventual saldo a pagar.', lancamento: 'D - Despesa de aluguel 8.000,00 / C - Caixa 8.000,00', ref: 'item 21' },
      { titulo: 'Remuneração dos diretores', situacao: 'No ano a empresa pagou R$ 600.000 de salários e R$ 40.000 de bônus aos três diretores.', tratamento: 'Divulga o total R$ 640.000, separando por categoria (curto prazo etc.).', lancamento: 'D - Despesa com administradores 640.000,00 / C - Caixa 640.000,00', ref: 'item 17' },
      { titulo: 'Venda entre empresas do mesmo grupo', situacao: 'A Indústria A vende R$ 2.000.000 em produtos para a Distribuidora B, ambas do mesmo grupo.', tratamento: 'Cada empresa divulga a venda/compra e o saldo em aberto; na consolidação, as transações entre elas são eliminadas.', lancamento: 'D - Clientes – partes relacionadas 2.000.000,00 / C - Receita de vendas 2.000.000,00', ref: 'itens 18 e 24' },
      { titulo: 'Controladora e controladora final', situacao: 'A empresa é controlada pela Holding X, que é controlada pela família Silva.', tratamento: 'Deve divulgar o nome da controladora direta e da controladora final, mesmo sem transações no ano.', lancamento: '—', ref: 'itens 13 a 16' },
      { titulo: 'Garantia dada pelo sócio', situacao: 'O sócio dá o próprio imóvel em garantia de um empréstimo bancário da empresa.', tratamento: 'Divulgar a garantia como transação com parte relacionada.', lancamento: '—', ref: 'item 21' },
      { titulo: 'Afirmação de condições de mercado', situacao: 'A administração escreve na nota: “as vendas ao grupo foram feitas em condições de mercado”.', tratamento: 'Só pode afirmar isso se tiver como comprovar (por exemplo, comparando com preços de terceiros).', lancamento: '—', ref: 'item 23' },
      { titulo: 'Provisão para créditos duvidosos', situacao: 'Há R$ 300.000 a receber de uma coligada e a empresa estima perda de R$ 50.000.', tratamento: 'Divulga o valor da perda estimada e a despesa reconhecida em relação à parte relacionada.', lancamento: 'D - Perdas esperadas 50.000,00 / C - (-) Perdas esperadas em crédito 50.000,00', ref: 'item 18' },
      { titulo: 'Itens agregados', situacao: 'A empresa tem 20 pequenas compras de serviços de coligadas, de natureza igual.', tratamento: 'Pode divulgar o total agregado, desde que o detalhe separado não seja necessário para entender o efeito.', lancamento: '—', ref: 'item 24' },
      { titulo: 'Compromissos futuros', situacao: 'A empresa se comprometeu a comprar de uma coligada R$ 5 milhões em insumos nos próximos 3 anos.', tratamento: 'Compromissos com partes relacionadas também são divulgados.', lancamento: '—', ref: 'item 18' },
    ],
  });

  C('NBC TG 06', 'R3', {
    resumo: 'Arrendamento é o “aluguel” de longo prazo de um bem, como um caminhão, uma loja ou um equipamento. Pela norma atual, quem aluga (o arrendatário) passa a registrar no balanço o direito de usar o bem e a dívida correspondente, em vez de lançar só a despesa de aluguel.',
    objetivo: 'Mostrar no balanço do arrendatário todos os direitos de uso e obrigações dos contratos de arrendamento (alinhado à norma internacional IFRS 16), e definir como o arrendador classifica seus contratos.',
    pontos: [
      { titulo: 'Quando existe um arrendamento', texto: 'O contrato é (ou contém) um arrendamento se dá o direito de controlar o uso de um ativo identificado por um período, em troca de pagamento.', ref: 'itens 9 a 11' },
      { titulo: 'Arrendatário: ativo + passivo', texto: 'No início, o arrendatário reconhece o ativo de direito de uso e o passivo de arrendamento (valor presente dos pagamentos futuros).', ref: 'item 22' },
      { titulo: 'Taxa de desconto', texto: 'Usa a taxa implícita do contrato, se for possível determiná-la; senão, a taxa incremental de financiamento do arrendatário.', ref: 'item 26' },
      { titulo: 'Depois do início', texto: 'O direito de uso é depreciado (resultado) e o passivo rende juros (resultado) e é reduzido a cada pagamento. A despesa de aluguel deixa de existir como tal.', ref: 'itens 29 a 40' },
      { titulo: 'Isenções permitidas', texto: 'Contratos de curto prazo (até 12 meses, sem opção de compra) e de ativos de baixo valor podem continuar a ser lançados como despesa linear de aluguel.', ref: 'itens 5 a 8' },
      { titulo: 'Reavaliação do passivo', texto: 'Se o prazo, o índice de reajuste ou as condições do contrato mudam, o passivo é remensurado e o ativo ajustado.', ref: 'itens 39 a 46' },
      { titulo: 'Arrendador: financeiro ou operacional', texto: 'Se o contrato transfere substancialmente os riscos e benefícios do ativo, é arrendamento financeiro (o arrendador baixa o bem e reconhece recebível). Senão, é operacional (o bem continua com ele e a receita é linear).', ref: 'itens 61 a 66' },
      { titulo: 'Venda com retroarrendamento', texto: 'Quando a empresa vende um bem e o aluga de volta, é preciso verificar se houve de fato uma venda e tratar o ganho conforme a norma.', ref: 'itens 98 a 103' },
    ],
    termos: [
      { termo: 'Ativo de direito de uso', significado: 'O direito do arrendatário de usar o bem durante o prazo do contrato.' },
      { termo: 'Passivo de arrendamento', significado: 'Valor presente dos pagamentos de arrendamento que ainda serão feitos.' },
      { termo: 'Taxa incremental sobre empréstimo', significado: 'A taxa que o arrendatário pagaria para tomar emprestado, com prazo e garantia semelhantes, o valor necessário para obter o bem.' },
      { termo: 'Prazo do arrendamento', significado: 'Período não cancelável mais períodos de renovação que a empresa tem certeza razoável de exercer.' },
      { termo: 'Arrendamento financeiro', significado: 'Contrato que transfere substancialmente todos os riscos e benefícios do bem ao arrendatário.' },
    ],
    exemplos: [
      { titulo: 'Aluguel de loja (reconhecimento inicial)', situacao: 'A empresa aluga uma loja por 5 anos, pagando R$ 10.000 por mês. Valor presente das parcelas, à taxa de 1% a.m.: R$ 449.550.', tratamento: 'Registra o direito de uso e o passivo pelo valor presente.', lancamento: 'D - Direito de uso – Imóveis 449.550,00 / C - Passivo de arrendamento 449.550,00', ref: 'item 22' },
      { titulo: 'Primeiro mês', situacao: 'Mesma loja. Juros do mês = 1% × 449.550 = 4.495,50; pagamento 10.000; depreciação 449.550/60 = 7.492,50.', tratamento: 'Reconhece juros, baixa o passivo e deprecia o direito de uso. Não há mais “despesa de aluguel” de R$ 10.000.', lancamento: 'D - Despesa financeira (juros) 4.495,50 / D - Passivo de arrendamento 5.504,50 / C - Caixa 10.000,00; D - Despesa de depreciação 7.492,50 / C - Depreciação acumulada – Direito de uso 7.492,50', ref: 'itens 29 a 38' },
      { titulo: 'Contrato curto', situacao: 'A empresa aluga um pavilhão para um evento por 6 meses, R$ 20.000 por mês.', tratamento: 'Arrendamento de curto prazo (≤ 12 meses): pode optar por lançar só despesa de aluguel.', lancamento: 'D - Despesa de aluguel 20.000,00 / C - Caixa 20.000,00', ref: 'item 6' },
      { titulo: 'Ativo de baixo valor', situacao: 'A empresa aluga notebooks por R$ 900 por mês, sendo cada um de baixo valor quando novo.', tratamento: 'Pode adotar a isenção de baixo valor e reconhecer despesa linear.', lancamento: 'D - Despesa de aluguel 900,00 / C - Caixa 900,00', ref: 'item 8' },
      { titulo: 'Reajuste por índice', situacao: 'O contrato da loja prevê reajuste pelo IPCA, e o índice subiu 4,5%.', tratamento: 'Os pagamentos futuros mudam; o passivo é remensurado e o ajuste vai para o direito de uso.', lancamento: 'D - Direito de uso 20.000,00 / C - Passivo de arrendamento 20.000,00', ref: 'itens 42 e 43' },
      { titulo: 'Renovação certa', situacao: 'A empresa decide, no ano 3, exercer a opção de renovar por mais 5 anos.', tratamento: 'O prazo muda; o passivo é reavaliado com taxa atualizada e o direito de uso é ajustado.', lancamento: 'D - Direito de uso 250.000,00 / C - Passivo de arrendamento 250.000,00', ref: 'itens 20 e 40' },
      { titulo: 'Arrendador: financeiro', situacao: 'Uma financeira arrenda uma máquina por toda a vida útil dela, com opção de compra por R$ 1.', tratamento: 'Para o arrendador é arrendamento financeiro: baixa o bem e registra um recebimento financiado.', lancamento: 'D - Arrendamentos a receber 300.000,00 / C - Máquinas (estoque ou imobilizado) 300.000,00', ref: 'itens 61 a 63' },
      { titulo: 'Arrendador: operacional', situacao: 'Uma construtora aluga um guindaste por 1 ano; o bem continua com ela e a vida útil é maior.', tratamento: 'Arrendamento operacional: o bem continua no imobilizado, e a receita é reconhecida de forma linear.', lancamento: 'D - Caixa 15.000,00 / C - Receita de arrendamento 15.000,00', ref: 'itens 81 e 82' },
      { titulo: 'Venda com retroarrendamento', situacao: 'A empresa vende um prédio por R$ 5.000.000 (valor justo) e o aluga de volta por 10 anos.', tratamento: 'Se for de fato venda, baixa o prédio, reconhece o direito de uso pelo percentual retido e o passivo, e só reconhece o ganho referente ao que foi transferido.', lancamento: '—', ref: 'itens 99 a 101' },
      { titulo: 'Contrato com serviço embutido', situacao: 'O contrato de “locação de equipamento” inclui R$ 3.000 por mês de manutenção.', tratamento: 'Separa o que é arrendamento e o que é serviço; só o componente arrendamento entra no passivo (a empresa pode optar por não separar, por classe de ativo).', lancamento: '—', ref: 'itens 12 a 17' },
    ],
    aviso: 'Valores dos exemplos são ilustrativos. Em contratos reais, a taxa de desconto e o prazo definem o resultado e merecem estudo caso a caso.',
  });

  C('NBC TG 07', 'R2', {
    resumo: 'O governo às vezes ajuda empresas com dinheiro, isenções ou financiamento barato. Esta norma diz como contabilizar essa ajuda (subvenção): ela deve virar resultado ao longo do tempo, em linha com os custos que ela veio compensar, e não ser lançada de uma vez nem direto no patrimônio.',
    objetivo: 'Definir quando e como reconhecer subvenções e outras assistências governamentais e o que divulgar sobre elas.',
    pontos: [
      { titulo: 'Condições para reconhecer', texto: 'Só se reconhece a subvenção quando há razoável segurança de que a empresa cumprirá as condições exigidas e de que a subvenção será recebida.', ref: 'item 7' },
      { titulo: 'Vai para o resultado, no ritmo dos custos', texto: 'A subvenção é reconhecida no resultado de forma sistemática, nos mesmos períodos em que a empresa tem os custos que ela compensa.', ref: 'itens 12 e 20' },
      { titulo: 'Subvenção para ativos', texto: 'Se a ajuda é para comprar um ativo, ela é apresentada como receita diferida (e reconhecida no resultado ao longo da vida do ativo) ou deduzida do valor do ativo.', ref: 'itens 24 a 28' },
      { titulo: 'Subvenção para resultado', texto: 'A ajuda que compensa despesas é apresentada como receita (ou dedução da despesa) nos períodos correspondentes.', ref: 'itens 29 a 31' },
      { titulo: 'Empréstimo com juros subsidiados', texto: 'A vantagem de juros abaixo do mercado é tratada como subvenção: mede-se o empréstimo pelo valor justo e a diferença é a subvenção.', ref: 'item 10A' },
      { titulo: 'Subvenção que precisa ser devolvida', texto: 'Se a empresa precisa devolver a subvenção, trata-se como mudança de estimativa, com ajuste imediato.', ref: 'itens 32 e 33' },
      { titulo: 'Divulgação', texto: 'A empresa divulga a política contábil adotada, a natureza e extensão das subvenções reconhecidas e condições não cumpridas.', ref: 'item 39' },
      { titulo: 'No Brasil: reserva de incentivos fiscais', texto: 'A subvenção para investimento (como incentivos de ICMS) vai para o resultado e depois pode ser destinada à reserva de lucros (incentivos fiscais) por decisão da assembleia, nos termos da lei societária.', ref: 'ver norma e legislação societária' },
    ],
    termos: [
      { termo: 'Subvenção governamental', significado: 'Ajuda do governo em forma de transferência de recursos em troca do cumprimento de condições passadas ou futuras.' },
      { termo: 'Assistência governamental', significado: 'Ação do governo para dar benefício econômico específico a empresas, que não gera um valor mensurável direto.' },
      { termo: 'Receita diferida', significado: 'Valor recebido que ainda não é receita e será reconhecido no resultado ao longo do tempo.' },
      { termo: 'Subvenção para investimento', significado: 'Ajuda ligada à construção, compra ou modernização de ativos.' },
      { termo: 'Razoável segurança', significado: 'Alta probabilidade de que a empresa cumprirá as condições e receberá a ajuda.' },
    ],
    exemplos: [
      { titulo: 'Subvenção para comprar máquina', situacao: 'O governo dá R$ 200.000 para a empresa comprar uma máquina de R$ 1.000.000, com vida útil de 10 anos.', tratamento: 'Reconhece o valor recebido como receita diferida e o leva ao resultado em 10 anos (R$ 20.000 por ano).', lancamento: 'D - Caixa 200.000,00 / C - Subvenção a apropriar (passivo) 200.000,00', ref: 'itens 24 a 28' },
      { titulo: 'Apropriação anual', situacao: 'No fim do primeiro ano, a máquina foi depreciada e a subvenção é apropriada.', tratamento: 'R$ 20.000 passam da receita diferida para o resultado.', lancamento: 'D - Subvenção a apropriar 20.000,00 / C - Receita de subvenção (resultado) 20.000,00', ref: 'item 12' },
      { titulo: 'Dedução do valor do ativo (alternativa)', situacao: 'A empresa prefere reduzir o ativo pela subvenção de R$ 200.000.', tratamento: 'A máquina fica no balanço por R$ 800.000; a depreciação menor reflete a subvenção.', lancamento: 'D - Caixa 200.000,00 / C - Imobilizado (máquina) 200.000,00', ref: 'item 24' },
      { titulo: 'Subvenção para cobrir despesas', situacao: 'Um programa paga R$ 60.000 para reduzir o custo de folha em 12 meses.', tratamento: 'Reconhece R$ 5.000 por mês como receita (ou redução da despesa).', lancamento: 'D - Caixa 60.000,00 / C - Subvenção a apropriar 60.000,00', ref: 'itens 29 a 31' },
      { titulo: 'Empréstimo com juros baixos', situacao: 'Programa de governo concede R$ 1.000.000 a 3% ao ano; o juro de mercado seria 10%. O valor justo da dívida é R$ 800.000.', tratamento: 'O empréstimo entra pelo valor justo (R$ 800.000) e a diferença (R$ 200.000) é a subvenção.', lancamento: 'D - Caixa 1.000.000,00 / C - Empréstimos 800.000,00 / C - Subvenção a apropriar 200.000,00', ref: 'item 10A' },
      { titulo: 'Condição não cumprida', situacao: 'A empresa recebeu uma subvenção condicionada a manter 100 empregos por 3 anos, mas demite metade no 2º ano.', tratamento: 'Passa a haver obrigação de devolver; ajusta imediatamente e divulga.', lancamento: 'D - Subvenção a apropriar 50.000,00 / C - Subvenção a devolver 50.000,00', ref: 'itens 32 e 33' },
      { titulo: 'Incentivo fiscal de ICMS', situacao: 'Estado concede crédito presumido de ICMS de R$ 120.000 no ano para a indústria investir.', tratamento: 'O benefício é reconhecido no resultado; depois, a empresa pode destinar o valor à reserva de incentivos fiscais (não pode distribuir como dividendos obrigatórios).', lancamento: 'D - ICMS a recolher 120.000,00 / C - Receita de subvenção para investimento 120.000,00', ref: 'ver norma' },
      { titulo: 'Assistência sem valor monetário', situacao: 'Prefeitura oferece consultoria técnica gratuita a pequenas empresas.', tratamento: 'Assistência sem valor mensurável: divulga a natureza do benefício, sem reconhecer valor.', lancamento: '—', ref: 'itens 34 a 38' },
      { titulo: 'Sem razoável segurança', situacao: 'Uma subvenção só será paga se a empresa ganhar uma licitação ainda incerta.', tratamento: 'Enquanto não houver razoável segurança, não reconhece a subvenção.', lancamento: '—', ref: 'item 7' },
      { titulo: 'Divulgação', situacao: 'A empresa recebeu três subvenções no ano.', tratamento: 'Divulga a política contábil, a natureza e o valor de cada uma, e as condições a cumprir.', lancamento: '—', ref: 'item 39' },
    ],
  });

  C('NBC TG 09', 'R1', {
    resumo: 'A Demonstração do Valor Adicionado (DVA) mostra quanto de riqueza a empresa criou e para quem ela foi distribuída: funcionários, governo (impostos), financiadores e sócios. É uma demonstração de “utilidade social”: de onde vem o valor e quem fica com ele.',
    objetivo: 'Divulgar o valor da riqueza gerada pela empresa e sua distribuição entre quem contribuiu para criá-la.',
    pontos: [
      { titulo: 'O que é valor adicionado', texto: 'É o que a empresa vende (receita) menos o que comprou de terceiros e consumiu (insumos). O resultado é a riqueza que ela gerou.', ref: 'ver norma' },
      { titulo: 'Quem tem que apresentar', texto: 'É obrigatória para companhias abertas; para as demais é recomendada. As empresas que a apresentam seguem o modelo da norma.', ref: 'ver norma' },
      { titulo: 'Primeira parte: geração da riqueza', texto: 'Receitas, menos insumos adquiridos de terceiros, igual a valor adicionado bruto; menos depreciação e amortização, igual a valor adicionado líquido; mais valor recebido em transferência (resultado de equivalência, receitas financeiras).', ref: 'ver norma' },
      { titulo: 'Segunda parte: distribuição', texto: 'Mostra para quem foi a riqueza: pessoal (salários, encargos), impostos e contribuições, remuneração de capitais de terceiros (juros e aluguéis) e de capitais próprios (dividendos e lucros retidos).', ref: 'ver norma' },
      { titulo: 'Os números vêm da contabilidade', texto: 'Cada valor da DVA deve ser compatível com a demonstração do resultado e as notas. A DVA não é uma contabilidade paralela.', ref: 'ver norma' },
      { titulo: 'Impostos na DVA', texto: 'Impostos sobre vendas (ICMS, PIS, COFINS) aparecem na DVA na receita bruta e na distribuição para o governo; a norma detalha o tratamento.', ref: 'ver norma' },
      { titulo: 'Consolidação', texto: 'Quando há demonstrações consolidadas, a DVA consolidada também é apresentada, eliminando transações internas.', ref: 'ver norma' },
      { titulo: 'Utilidade', texto: 'Ajuda a entender o peso de cada grupo (empregados, governo, financiadores, sócios) e o impacto social da empresa.', ref: 'ver norma' },
    ],
    termos: [
      { termo: 'Valor adicionado bruto', significado: 'Receitas menos insumos adquiridos de terceiros.' },
      { termo: 'Valor adicionado líquido', significado: 'Valor adicionado bruto menos depreciação, amortização e exaustão.' },
      { termo: 'Valor adicionado total a distribuir', significado: 'Valor adicionado líquido mais o valor recebido em transferência.' },
      { termo: 'Insumos adquiridos de terceiros', significado: 'Custo das mercadorias vendidas, materiais, energia, serviços de terceiros e outros comprados fora.' },
      { termo: 'Valor recebido em transferência', significado: 'Riqueza criada por outras empresas e recebida (equivalência patrimonial, receitas financeiras, aluguéis).' },
    ],
    exemplos: [
      { titulo: 'Receita da DVA', situacao: 'Vendas de R$ 1.000.000 (já com ICMS incluído) e baixa de perdas esperadas de R$ 10.000.', tratamento: 'Receitas = 1.000.000 − 10.000 = R$ 990.000.', lancamento: '—', ref: 'ver norma' },
      { titulo: 'Insumos de terceiros', situacao: 'A empresa comprou mercadorias, materiais e serviços de R$ 520.000 (incluindo impostos recuperáveis).', tratamento: 'Aparecem em “insumos adquiridos de terceiros”.', lancamento: '—', ref: 'ver norma' },
      { titulo: 'Valor adicionado bruto e líquido', situacao: 'Receitas R$ 990.000; insumos R$ 520.000; depreciação R$ 40.000.', tratamento: 'Bruto = 470.000; líquido = 430.000.', lancamento: '—', ref: 'ver norma' },
      { titulo: 'Valor recebido em transferência', situacao: 'A empresa teve R$ 15.000 de receitas financeiras e R$ 20.000 de equivalência patrimonial.', tratamento: 'Somam R$ 35.000 a distribuir: total = 430.000 + 35.000 = R$ 465.000.', lancamento: '—', ref: 'ver norma' },
      { titulo: 'Distribuição ao pessoal', situacao: 'Salários, encargos e benefícios totalizam R$ 200.000.', tratamento: 'Aparece em “pessoal” (cerca de 43% do total).', lancamento: '—', ref: 'ver norma' },
      { titulo: 'Distribuição ao governo', situacao: 'Impostos e contribuições (ICMS, INSS, IRPJ etc.) somam R$ 130.000.', tratamento: 'Aparecem em “impostos, taxas e contribuições” (cerca de 28%).', lancamento: '—', ref: 'ver norma' },
      { titulo: 'Remuneração de terceiros', situacao: 'Juros pagos R$ 45.000 e aluguéis R$ 30.000.', tratamento: 'Vão para “remuneração de capitais de terceiros” (R$ 75.000).', lancamento: '—', ref: 'ver norma' },
      { titulo: 'Remuneração dos sócios', situacao: 'Dividendos de R$ 20.000 e lucros retidos de R$ 40.000.', tratamento: 'Vão para “remuneração de capitais próprios” (R$ 60.000).', lancamento: '—', ref: 'ver norma' },
      { titulo: 'Fechamento', situacao: 'Pessoal 200.000 + impostos 130.000 + terceiros 75.000 + próprios 60.000.', tratamento: 'O total distribuído (R$ 465.000) deve ser igual ao valor adicionado total a distribuir.', lancamento: '—', ref: 'ver norma' },
      { titulo: 'Quem deve apresentar', situacao: 'Uma sociedade limitada de pequeno porte, sem registro na CVM.', tratamento: 'A DVA não é obrigatória; pode apresentá-la voluntariamente.', lancamento: '—', ref: 'ver norma' },
    ],
    aviso: 'A DVA é uma demonstração de organização de números que já existem na contabilidade; por isso não há lançamentos próprios. As etiquetas “ver norma” indicam que o item exato deve ser conferido na norma original.',
  });

  C('NBC TG 10', 'R3', {
    resumo: 'Às vezes a empresa paga funcionários, diretores ou fornecedores com ações ou opções de compra de ações (ou com um valor em dinheiro atrelado ao preço das ações). Esta norma manda registrar isso como despesa, medida pelo valor justo, ao longo do tempo em que o beneficiado “conquista” o direito.',
    objetivo: 'Definir como contabilizar transações em que a empresa recebe bens ou serviços e paga com ações, opções ou valores ligados ao preço das ações.',
    pontos: [
      { titulo: 'Qual a ideia central', texto: 'Quem recebe serviços pagando em ações também tem um custo: a empresa deve reconhecer a despesa (ou o ativo) e o aumento do patrimônio ou do passivo correspondente.', ref: 'itens 7 e 8' },
      { titulo: 'Liquidado com ações (patrimonial)', texto: 'O valor justo dos instrumentos na data da outorga é a despesa total, reconhecida durante o período de carência (vesting), contra o patrimônio líquido. Não é refeito depois.', ref: 'itens 10 a 15' },
      { titulo: 'Liquidado em dinheiro', texto: 'Quando a empresa paga em caixa um valor ligado ao preço da ação, reconhece um passivo, que é reavaliado ao valor justo a cada balanço até a liquidação, e a variação vai para o resultado.', ref: 'itens 30 a 33' },
      { titulo: 'Condições de aquisição (vesting)', texto: 'Há condições de serviço (ficar na empresa por X anos) e de desempenho (atingir metas). A despesa é distribuída ao longo do período de carência esperado.', ref: 'itens 15 a 21' },
      { titulo: 'Mensuração do valor justo', texto: 'Para opções, usa-se normalmente modelos como Black-Scholes ou binomial, considerando preço da ação, preço de exercício, prazo, volatilidade, dividendos e juros.', ref: 'itens 16 a 24' },
      { titulo: 'Transações com terceiros não empregados', texto: 'Mede-se pelo valor justo dos bens ou serviços recebidos; se não for possível, pelo valor justo dos instrumentos.', ref: 'item 13' },
      { titulo: 'Modificações e cancelamentos', texto: 'Se o plano é alterado a favor do empregado, o aumento no valor justo é reconhecido; cancelamentos aceleram o reconhecimento.', ref: 'itens 26 a 29' },
      { titulo: 'Divulgação', texto: 'Descrição do plano, número e preço médio das opções em circulação, método de valorização e efeito no resultado.', ref: 'itens 44 a 52' },
    ],
    termos: [
      { termo: 'Data de outorga', significado: 'Data em que a empresa e a outra parte concordam com o acordo de pagamento baseado em ações.' },
      { termo: 'Período de carência (vesting)', significado: 'Tempo ou condições que o beneficiado precisa cumprir para ganhar o direito aos instrumentos.' },
      { termo: 'Opção de compra de ações', significado: 'Direito de comprar ações no futuro por preço pré-fixado (preço de exercício).' },
      { termo: 'Valor justo na outorga', significado: 'Valor estimado dos instrumentos na data em que são concedidos.' },
      { termo: 'Liquidação em caixa', significado: 'Quando a empresa paga em dinheiro, calculado sobre o valor das ações.' },
    ],
    exemplos: [
      { titulo: 'Opções a funcionários', situacao: 'A empresa concede 100.000 opções a executivos, com valor justo de R$ 3 cada na outorga, e carência de 3 anos de serviço.', tratamento: 'Despesa total de R$ 300.000, reconhecida em 3 anos (R$ 100.000 por ano) contra o patrimônio líquido.', lancamento: 'D - Despesa com pagamento baseado em ações 100.000,00 / C - Reserva de capital – Opções outorgadas 100.000,00', ref: 'itens 10 a 15' },
      { titulo: 'Funcionário sai antes', situacao: 'No exemplo anterior, 10% dos executivos deixam a empresa no 2º ano.', tratamento: 'A estimativa de opções que serão efetivamente adquiridas é revisada, e o ajuste vai para o resultado do período.', lancamento: 'D - Reserva de capital 20.000,00 / C - Despesa com pagamento baseado em ações (reversão) 20.000,00', ref: 'itens 19 e 20' },
      { titulo: 'Valor justo não muda depois', situacao: 'Após a outorga, o preço da ação cai e o valor justo das opções cai pela metade.', tratamento: 'Nas opções liquidadas com ações, o valor justo da outorga NÃO é refeito; a despesa continua baseada no valor original.', lancamento: '—', ref: 'item 19' },
      { titulo: 'Plano liquidado em dinheiro (SARs)', situacao: 'A empresa promete pagar em dinheiro, daqui a 3 anos, o aumento do preço de 50.000 ações. Valor justo estimado no 1º ano: R$ 6 por direito.', tratamento: 'Reconhece passivo e despesa proporcionais: 50.000 × 6 × 1/3 = R$ 100.000; reavalia a cada balanço.', lancamento: 'D - Despesa com remuneração baseada em ações 100.000,00 / C - Passivo – Remuneração baseada em ações 100.000,00', ref: 'itens 30 a 33' },
      { titulo: 'Reavaliação do passivo', situacao: 'No 2º ano o valor justo sobe para R$ 9; o passivo acumulado deve ser 50.000 × 9 × 2/3 = R$ 300.000.', tratamento: 'Ajusta o passivo de R$ 100.000 para R$ 300.000 e reconhece despesa adicional de R$ 200.000.', lancamento: 'D - Despesa com remuneração baseada em ações 200.000,00 / C - Passivo – Remuneração baseada em ações 200.000,00', ref: 'item 30' },
      { titulo: 'Pagamento de fornecedor em ações', situacao: 'A empresa contrata uma consultoria e paga com 10.000 ações, em vez de dinheiro; o valor justo do serviço recebido é de R$ 150.000.', tratamento: 'Mede pelo valor justo do serviço recebido.', lancamento: 'D - Despesa com consultoria 150.000,00 / C - Capital social / Reserva de capital 150.000,00', ref: 'item 13' },
      { titulo: 'Condição de desempenho', situacao: 'As opções só são adquiridas se o lucro crescer 10% ao ano por 3 anos.', tratamento: 'A empresa estima quantas opções serão adquiridas e, no fim, reconhece apenas as realmente adquiridas.', lancamento: '—', ref: 'itens 15 a 21' },
      { titulo: 'Modificação favorável', situacao: 'Após queda da ação, a empresa reduz o preço de exercício das opções, aumentando seu valor justo em R$ 50.000.', tratamento: 'O aumento é reconhecido como despesa adicional no período restante de carência.', lancamento: 'D - Despesa com pagamento baseado em ações 50.000,00 / C - Reserva de capital 50.000,00', ref: 'itens 26 a 28' },
      { titulo: 'Cancelamento', situacao: 'A empresa cancela o plano no 2º ano, sem substituir.', tratamento: 'O que faltava reconhecer é reconhecido imediatamente (aceleração).', lancamento: 'D - Despesa com pagamento baseado em ações 100.000,00 / C - Reserva de capital 100.000,00', ref: 'item 28' },
      { titulo: 'Divulgação', situacao: 'Fim do ano com 3 planos em aberto.', tratamento: 'Descreve cada plano, mostra opções em circulação, preço de exercício médio, o método de cálculo do valor justo e o efeito na despesa.', lancamento: '—', ref: 'itens 44 a 52' },
    ],
  });
})();
